function Landing(){return <><Header/><main className="vitra-home"><section className="home-hero"><div className="home-hero-copy"><span className="home-kicker"><Icon name="spark" size={15}/> Clinical research, made clearer</span><h1>Find the next step in your health journey.</h1><p>Vitra makes clinical trial discovery easier to understand—helping patients explore real studies and researchers connect with consent-aware potential matches.</p><div className="home-actions"><Button onClick={()=>go('/signup?role=patient')}>Explore clinical trials <Icon name="arrow" size={17}/></Button><Button kind="secondary" onClick={()=>go('/signup?role=researcher')}>For researchers</Button></div></div><div className="home-hero-visual" aria-label="Illustration of a potential trial match"><div className="visual-glow"/><div className="visual-orbit orbit-one"/><div className="visual-orbit orbit-two"/><div className="visual-core"><Icon name="flask" size={48}/></div><article className="home-match-preview"><div><Badge tone="green">Potential relevance</Badge><span className="match-percent">84%</span></div><h3>A study to explore</h3><p>Type 2 diabetes · New Brunswick, NJ</p><div className="preview-rule"><Icon name="check" size={14}/> Topic aligns with your profile</div><div className="preview-rule"><Icon name="check" size={14}/> Location preference noted</div><small>Screening is still required</small></article><div className="hero-note note-top"><Icon name="shield" size={19}/><span><b>You stay in control</b><small>Consent-aware sharing</small></span></div><div className="hero-note note-bottom"><Icon name="book" size={19}/><span><b>Real study records</b><small>ClinicalTrials.gov source</small></span></div></div></section><section id="how" className="home-how"><div className="home-section-heading"><span className="eyebrow">How Vitra works</span><h2>Simple steps. Clear context.</h2></div><div className="home-steps"><Feature num="01" icon="user" title="Choose what to share" text="Use fictional information in the demo profile and leave unknown details unknown."/><Feature num="02" icon="search" title="Explore study records" text="Search real ClinicalTrials.gov listings and view their original study details."/><Feature num="03" icon="spark" title="Understand the next step" text="Review preliminary relevance information; qualified study teams conduct screening."/></div></section><section id="about" className="home-about"><div className="home-about-image" role="img" aria-label="A clinician talking with a patient"/><div className="home-about-copy"><span className="eyebrow">About Vitra</span><h2>Research starts with people.</h2><p>Clinical research brings participants and study teams together around questions that matter. Vitra helps people explore public study records, understand the next step, and make an informed choice without promising eligibility or enrollment.</p><div className="about-points"><span><Icon name="check" size={16}/> Real public study records</span><span><Icon name="check" size={16}/> Clear, reviewable context</span><span><Icon name="check" size={16}/> Respect for informed choice</span></div><small>Illustrative image of a clinical care team.</small></div></section><section className="home-safety"><Icon name="check"/><div><h3>Critical criteria. Clear eligibility context.</h3><p>Review the requirements listed for each study. Only the study team can confirm eligibility during screening.</p></div></section><section className="home-paths home-paths-centered"><div className="home-paths-intro"><span className="eyebrow">Choose your path</span><h2>Designed for the people moving research forward.</h2><p>Vitra helps people explore public study records and gives research teams clearer tools for reviewing study criteria.</p><a className="home-paths-main-cta" href="/clinical-trial-guide">View the clinical trial guide <span aria-hidden="true">→</span></a></div><div className="path-grid"><article id="patients" className="path-card patient-path"><span className="path-icon-circle"><Icon name="user" size={38}/></span><span className="path-label">For patients</span><h3>Explore studies at your own pace.</h3><p>Browse real trial records, understand the listed criteria, and save studies to revisit.</p><div className="path-card-action"><Button onClick={()=>go('/signup?role=patient')}>Enter patient portal <Icon name="arrow" size={16}/></Button></div></article><article id="researchers" className="path-card researcher-path"><span className="path-icon-circle"><Icon name="flask" size={38}/></span><span className="path-label">For researchers</span><h3>Review study criteria with clarity.</h3><p>Organize protocol requirements, inspect source text, and review explainable preliminary matches.</p><div className="path-card-action"><Button kind="secondary" onClick={()=>go('/signup?role=researcher')}>Enter researcher portal <Icon name="arrow" size={16}/></Button></div></article></div></section><HomepageFaq/></main><Footer/></>}
